<script lang="ts">
 import {invalidateAll} from '$app/navigation';let {model,t,role}:{model:Record<string,Record<string,any>[]>;t:(s:string)=>string;role:string}=$props();let project=$state(''),style=$state(''),budget=$state(''),reference=$state(''),recipe=$state(''),vessel=$state(''),pump=$state(''),resource=$state(''),title=$state(''),start=$state(''),end=$state(''),route=$state(''),busy=$state(false),message=$state(''),result=$state<any>(null),targets=$state<Record<string,string>>({}),limits=$state<Record<string,string>>({});
 function load(){const b=model.briefs.find(b=>b.project_id===project);style=b?.style??'';budget=b?.budget??'';reference=b?.reference_lot_id??'';targets={};limits={};for(const [p,r] of Object.entries(b?.targets??{}) as [string,any][])for(const k of ['minimum','maximum'])targets[p+'_'+k]=r[k];for(const [id,r] of Object.entries(b?.share_limits??{}) as [string,any][])for(const k of ['minimum','maximum'])limits[id+'_'+k]=r[k];}
 async function submit(body:Record<string,any>){busy=true;message='';try{const res=await fetch('/api/planning',{method:'POST',headers:{'content-type':'application/json','idempotency-key':crypto.randomUUID()},body:JSON.stringify(body)});const r=await res.json();if(res.ok){if(body.action==='check')result=r;else{message=t('saved');await invalidateAll();}}else message=t(r.message);}catch{message=t('CONNECTION_FAILED');}finally{busy=false;}}
 function brief(){const ranges=Object.fromEntries(['alcohol','sugar','acidity'].filter(p=>targets[p+'_minimum']||targets[p+'_maximum']).map(p=>[p,{minimum:targets[p+'_minimum']||'0',maximum:targets[p+'_maximum']||'1000'}]));const shares=Object.fromEntries(model.positions.filter(p=>limits[p.id+'_minimum']||limits[p.id+'_maximum']).map(p=>[p.id,{minimum:limits[p.id+'_minimum']||'0',maximum:limits[p.id+'_maximum']||'100'}]));submit({action:'brief',project_id:project,style,budget:budget||undefined,reference_lot_id:reference||undefined,targets:ranges,share_limits:shares,expected_version:model.briefs.find(b=>b.project_id===project)?.version});}
</script>
<section class="card"><h2>{t('planBrief')}</h2><p class="muted">{t('projectionOnly')}</p>{#if ['owner','oenologist'].includes(role)}<form onsubmit={(e)=>{e.preventDefault();brief();}}><div class="grid"><label>{t('project_id')}<select required bind:value={project} onchange={load}><option value="">—</option>{#each model.projects as p}<option value={p.id}>{p.name}</option>{/each}</select></label><label>{t('budget')}<input bind:value={budget} /></label><label>{t('reference_lot_id')}<select bind:value={reference}><option value="">—</option>{#each model.lots as l}<option value={l.id}>{l.code} · {l.vintage}</option>{/each}</select></label></div><label>{t('style')}<textarea bind:value={style} maxlength="5000"></textarea></label><div class="grid">{#each ['alcohol','sugar','acidity'] as p}<label>{t(p)} · {t('minimum')} / {t('maximum')}<input aria-label={t(p)+' '+t('minimum')} bind:value={targets[p+'_minimum']} /><input aria-label={t(p)+' '+t('maximum')} bind:value={targets[p+'_maximum']} /></label>{/each}</div><details><summary>{t('shareLimits')}</summary>{#each model.positions as p}<div class="grid"><label>{p.lot_code} · {t('minimum')} %<input bind:value={limits[p.id+'_minimum']} /></label><label>{t('maximum')} %<input bind:value={limits[p.id+'_maximum']} /></label></div>{/each}</details><button disabled={busy}>{t('saveBrief')}</button></form>{/if}<form onsubmit={(e)=>{e.preventDefault();submit({action:'check',recipe_id:recipe,target_vessel_id:vessel,pump_id:pump||undefined});}}><div class="grid"><label>{t('recipe_id')}<select required bind:value={recipe}><option value="">—</option>{#each model.recipes as r}<option value={r.id}>{r.name} · v{r.revision}</option>{/each}</select></label><label>{t('target_vessel_id')}<select required bind:value={vessel}><option value="">—</option>{#each model.vessels as v}<option value={v.id}>{v.code} · {v.capacity_l} L · {t(v.status)}</option>{/each}</select></label><label>{t('pump')}<select bind:value={pump}><option value="">—</option>{#each model.resources.filter(r=>r.kind==='pump') as r}<option value={r.id}>{r.name} · {t(r.status)}</option>{/each}</select></label></div><button disabled={busy}>{t('scaleUpCheck')}</button></form>{#if result}<p>{t(result.feasible?'passed':'failed')}</p>{#each result.issues as issue}<p>{t(issue)}</p>{/each}{#each result.sources as s}<p>{model.positions.find(p=>p.id===s.position_id)?.lot_code} · {s.quantity_l} L / {s.available_l??'—'} L</p>{/each}{/if}<p role="status">{message}</p></section>
<section class="card"><h2>{t('resourcePlan')}</h2><form onsubmit={(e)=>{e.preventDefault();submit({action:'booking',resource_id:resource,vessel_id:vessel||undefined,project_id:project||undefined,title,starts_at:new Date(start).toISOString(),ends_at:new Date(end).toISOString(),route});}}><div class="grid"><label>{t('resource_id')}<select required bind:value={resource}><option value="">—</option>{#each model.resources as r}<option value={r.id}>{r.name} · {t(r.status)}</option>{/each}</select></label><label>{t('title')}<input required bind:value={title} maxlength="160" /></label><label>{t('starts_at')}<input type="datetime-local" required bind:value={start} /></label><label>{t('ends_at')}<input type="datetime-local" required bind:value={end} /></label></div><label>{t('instructions')}<textarea required bind:value={route} maxlength="2000"></textarea></label><button disabled={busy}>{t('save')}</button></form>{#each model.resource_bookings??[] as b}<article><strong>{b.title}</strong><p>{b.resource_name} · {b.starts_at}–{b.ends_at} · {t(b.status)}</p><p>{b.route}</p>{#if !['done','cancelled'].includes(b.status)}{#each ['doing','done','cancelled'] as status}<button disabled={busy} onclick={()=>submit({action:'status',id:b.id,expected_version:b.version,status})}>{t(status)}</button>{/each}{/if}</article>{/each}</section>
<style>.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:14px;margin:15px 0}form{margin:24px 0}article{border-top:1px solid #e0e5dc;padding:18px 0}button{margin:10px 8px 10px 0}textarea{width:100%}</style>
